mapper.select:
SELECT cai.id, cai.orgId, cai.orgName, cai.accountItemId, cai.accountTypeId, cai.accountTypeName, cai.accountItemName, cai.type, cai.inservice FROM ( SELECT cai.id, ifnull(cai.company_id, cei.company_id) AS orgId, ifnull( cei.abbreviation, '公司' ) AS orgName, ai.accountTypeId, ai.accountTypeName, ifnull(cai.account_item_id, ai.accountItemId) AS accountItemId, ai.accountItemName, ai.type, ifnull(cai.inservice, 1) as inservice FROM clinic_account_item cai LEFT JOIN ( SELECT ai.id AS accountItemId, ai.`name` AS accountItemName, ai.type, a.id AS accountTypeId, a.`name` AS accountTypeName FROM account_item ai LEFT JOIN account_type a ON ai.account_type_id = a.id ) ai ON cai.account_item_id = ai.accountItemId LEFT JOIN clinic_ext_info cei ON cai.company_id = cei.company_id ) cai
and cai.id = #{queryForm.id}
and cai.accountTypeId = #{queryForm.accountTypeId}
and cai.accountItemId = #{queryForm.accountItemId}
and cai.orgId = #{queryForm.orgId}
and cai.inservice = #{queryForm.inservice}

SELECT ai.id as accountItemId, ai.name as accountItemName, ai.account_type_id as accountTypeId, act.name as accountTypeName, ai.type, ai.inservice FROM account_item ai LEFT JOIN account_type act on ai.account_type_id = act.id INNER JOIN clinic_account_item cai ON ai.id = cai.account_item_id
AND ai.inservice = true AND cai.inservice = true and cai.company_id = #{orgId}
AND ai.type IN
#{type}
